nc-time-based-key-value-store#1.main:
public class Main {
    public static void main(String[] args) throws Exception {
        java.util.List<Object> in = runner.In.values(System.in);
        java.util.List<Object> ops = runner.In.list(runner.In.arg(in, 0, "operations"));
        java.util.List<Object> argv = in.size() > 1 ? runner.In.list(in.get(1)) : new java.util.ArrayList<Object>();
        StringBuilder out = new StringBuilder("[");
        TimeMap obj = null;
        for (int i = 0; i < ops.size(); i++) {
            String op = runner.In.toStr(ops.get(i));
            java.util.List<Object> a = i < argv.size() ? runner.In.list(argv.get(i)) : new java.util.ArrayList<Object>();
            if (i > 0) out.append(", ");
            switch (op) {
                case "TimeMap": obj = new TimeMap(); out.append("null"); break;
                case "set": need(obj); obj.set(runner.In.toStr(runner.In.arg(a, 0, "key")), runner.In.toStr(runner.In.arg(a, 1, "value")), runner.In.toInt(runner.In.arg(a, 2, "timestamp"))); out.append("null"); break;
                case "get": need(obj); out.append(runner.Show.of(obj.get(runner.In.toStr(runner.In.arg(a, 0, "key")), runner.In.toInt(runner.In.arg(a, 1, "timestamp"))))); break;
                default: throw new IllegalArgumentException("unknown operation " + op);
            }
        }
        System.out.println(out.append("]"));
    }
    private static void need(Object obj) {
        if (obj == null) throw new IllegalStateException("the first operation must be \"TimeMap\"");
    }
}

